window.RP_SESSION={"id":"S-e4bdc99ac4f2","messages":[{"id":"RP-II-0103549","time":"2026-05-23T01:05:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"...","characters":["P-216ccc194078"]},{"id":"RP-II-0103550","time":"2026-05-23T01:06:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"늦은 밤 —어쩌면 새벽—, 니콜라스는 길드 회관의 식탁에 가만히 앉아 시간만 죽이고 있었습니다. 늘 일에 치여 사는 그에게는 보기 드문 광경이죠. 하지만 정말로 할 일이 없었습니다.","characters":["P-216ccc194078"]},{"id":"RP-II-0103551","time":"2026-05-23T01:06:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"읽을만한 책은 다 읽었고, 재독도 무의미해지는 시점이 오기 마련입니다. 이럴 때는 도대체 무얼 해야 하죠?","characters":["P-216ccc194078"]},{"id":"RP-II-0103552","time":"2026-05-23T01:06:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"...","characters":["P-216ccc194078"]},{"id":"RP-II-0103553","time":"2026-05-23T01:06:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"그는 골똘히 생각하다가, 끝내 뭔가 떠올려내고는 계단을 올랐습니다. 잠시 뒤 다시 내려온 그의 손에는 체스 판이 들려 있었습니다.","characters":["P-216ccc194078"]},{"id":"RP-II-0103554","time":"2026-05-23T01:07:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"니콜라스는 식탁에 체스판을 펴서 올려두었습니다. 그리고는 모든 기물을 제자리에 배치하고.","characters":["P-216ccc194078"]},{"id":"RP-II-0103555","time":"2026-05-23T01:07:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"하얀 말을 옮겼습니다.","characters":["P-216ccc194078"]},{"id":"RP-II-0103556","time":"2026-05-23T01:07:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"...그리고는 반대편 의자로 걸어가 앉아 검은 말을 옮겼습니다.","characters":["P-216ccc194078"]},{"id":"RP-II-0103557","time":"2026-05-23T01:07:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"흰 말을 옮기고, 검은 말을 옮기고...\n\n이 짓을 계속 하다가, 검은 말을 움직일 차례가 된 그는 머리를 싸매고는 말했습니다.","characters":["P-216ccc194078"]},{"id":"RP-II-0103558","time":"2026-05-23T01:08:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"젠장! 플린트, 네가 이긴 모양인데.\"","characters":["P-216ccc194078"]},{"id":"RP-II-0103559","time":"2026-05-23T01:08:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"다시 맞은 편 의자로 향하고는,","characters":["P-216ccc194078"]},{"id":"RP-II-0103560","time":"2026-05-23T01:08:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"체크메이트.\"\n\n\"다음에도 한 판 하자고, 닉.\"","characters":["P-216ccc194078"]},{"id":"RP-II-0103561","time":"2026-05-23T01:08:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"정적.","characters":["P-216ccc194078"]},{"id":"RP-II-0103562","time":"2026-05-23T01:09:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"혼자만 있는데 이렇게 어색할 수가 있나요.","characters":["P-216ccc194078"]},{"id":"RP-II-0103563","time":"2026-05-23T01:10:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"두 손을 마주 잡습니다. 아마 악수한답시고 하는 짓일 겁니다.","characters":["P-216ccc194078"]},{"id":"RP-II-0103564","time":"2026-05-23T01:20:00+09:00","room":"RP II","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-216ccc194078"]},{"id":"RP-II-0103565","time":"2026-05-23T01:20:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
